const daysBack = $input.first().json.days_back || 7;
const sinceDate = new Date();
sinceDate.setDate(sinceDate.getDate() - daysBack);

return [
  {
    json: {
      ...$input.first().json,
      since_iso: sinceDate.toISOString(),
      report_start: sinceDate.toISOString().split('T')[0],
      report_end: new Date().toISOString().split('T')[0]
    }
  }
];

const config = $('Calculate Date Range').first().json;

// Safely collect commits
const commitsItems = $('Fetch Weekly Commits').all() || [];
const commits = commitsItems.map(item => {
  const c = item.json;
  return {
    sha: c.sha ? c.sha.substring(0, 7) : '',
    message: c.commit && c.commit.message ? c.commit.message.split('\n')[0] : '',
    author: c.commit && c.commit.author ? c.commit.author.name : 'Unknown'
  };
}).slice(0, 50);

// Safely collect closed issues (filter out pull requests)
const issuesItems = $('Fetch Closed Issues').all() || [];
const closedIssues = issuesItems
  .filter(item => !item.json.pull_request)
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    author: item.json.user ? item.json.user.login : 'Unknown'
  }));

// Safely collect merged PRs
const prItems = $('Fetch Merged PRs').all() || [];
const mergedPRs = prItems
  .filter(item => item.json.merged_at && new Date(item.json.merged_at) >= new Date(config.since_iso))
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    author: item.json.user ? item.json.user.login : 'Unknown'
  }));

return [
  {
    json: {
      ...config,
      activity_stats: {
        commits_count: commits.length,
        closed_issues_count: closedIssues.length,
        merged_prs_count: mergedPRs.length
      },
      raw_activity: {
        commits,
        closed_issues: closedIssues,
        merged_prs: mergedPRs
      }
    }
  }
];

