const claudeResponse = $input.first().json;
const aggregateData = $('Aggregate Activity Data').first().json;

let narrative = 'No summary generated.';
if (claudeResponse && claudeResponse.content && claudeResponse.content[0]) {
  narrative = claudeResponse.content[0].text;
} else if (claudeResponse && claudeResponse.text) {
  narrative = claudeResponse.text;
}

// Format Discord / Slack payload
const payload = {
  content: `📢 **Weekly Dev Summary:** \`${aggregateData.github_owner}/${aggregateData.github_repo}\` (${aggregateData.report_start} to ${aggregateData.report_end})\n\n` + narrative
};

return [
  {
    json: {
      webhook_url: aggregateData.destination_webhook,
      payload,
      narrative
    }
  }
];
